export const complex = (re = 0, im = 0) => [re, im];
export const add = (a, b) => [a[0] + b[0], a[1] + b[1]];
export const sub = (a, b) => [a[0] - b[0], a[1] - b[1]];
export const scale = (a, s) => [a[0] * s, a[1] * s];
export const mul = (a, b) => [a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0]];
export const conjugate = a => [a[0], -a[1]];
export const abs2 = a => a[0] * a[0] + a[1] * a[1];
export const abs = a => Math.hypot(a[0], a[1]);
export const cis = theta => [Math.cos(theta), Math.sin(theta)];

// H(t) = (1+u) erfcx(exp(i*pi/4)*u), u=t/(1-t), 0 <= t <= 1.
// Its finite endpoint at t=1 eliminates overflow and cancellation at high kL.
