  const difference = phi_o - phi_i, sum = phi_o + phi_i;
  const a = add(stableCotTransition(difference, n, k * L, 1, boundaryEps), stableCotTransition(difference, n, k * L, -1, boundaryEps));
  const b = add(stableCotTransition(sum, n, k * L, 1, boundaryEps), stableCotTransition(sum, n, k * L, -1, boundaryEps));
